-- v3.0-RTI: statutory tax and payroll tables (PPh 21 TER, PTKP, Pasal 17, PPN/PPh rates, BPJS) + payroll run.
-- GENERATED by scripts/rti/build-migrations.cjs from src/lib/rti/tax-tables.ts. Amounts are integer cents.
-- Regulatory changes are new effective-dated rows; existing rows are immutable.
CREATE TABLE india_tax_ter_brackets(
 category TEXT NOT NULL CHECK(category IN ('A','B','C','DAILY')),seq INTEGER NOT NULL CHECK(seq>0),
 lower_cents INTEGER NOT NULL CHECK(lower_cents>=0),upper_cents INTEGER CHECK(upper_cents IS NULL OR upper_cents>lower_cents),
 rate TEXT NOT NULL,effective_from TEXT NOT NULL,effective_to TEXT,legal_basis TEXT NOT NULL,
 PRIMARY KEY(category,seq,effective_from)
);
CREATE TABLE india_tax_ptkp(
 status TEXT NOT NULL CHECK(status IN ('TK/0','TK/1','TK/2','TK/3','K/0','K/1','K/2','K/3')),annual_cents INTEGER NOT NULL CHECK(annual_cents>0),
 ter_category TEXT NOT NULL CHECK(ter_category IN ('A','B','C')),effective_from TEXT NOT NULL,effective_to TEXT,legal_basis TEXT NOT NULL,
 PRIMARY KEY(status,effective_from)
);
CREATE TABLE india_tax_progressive_brackets(
 schedule TEXT NOT NULL,seq INTEGER NOT NULL,upper_cents INTEGER,rate TEXT NOT NULL,effective_from TEXT NOT NULL,effective_to TEXT,legal_basis TEXT NOT NULL,
 PRIMARY KEY(schedule,seq,effective_from)
);
CREATE TABLE india_tax_rates(
 code TEXT NOT NULL,description TEXT NOT NULL,rate TEXT NOT NULL,dpp_factor TEXT NOT NULL DEFAULT '1',base TEXT NOT NULL,
 coretax_code TEXT,effective_from TEXT NOT NULL,effective_to TEXT,legal_basis TEXT NOT NULL,PRIMARY KEY(code,effective_from)
);
CREATE TABLE india_payroll_contribution_rates(
 program TEXT NOT NULL,party TEXT NOT NULL CHECK(party IN ('employer','employee')),rate TEXT NOT NULL,wage_cap_cents INTEGER,
 effective_from TEXT NOT NULL,effective_to TEXT,legal_basis TEXT NOT NULL,PRIMARY KEY(program,party,effective_from)
);
CREATE TABLE india_payroll_jkk_classes(
 class INTEGER NOT NULL CHECK(class BETWEEN 1 AND 5),label TEXT NOT NULL,rate TEXT NOT NULL,effective_from TEXT NOT NULL,legal_basis TEXT NOT NULL,
 PRIMARY KEY(class,effective_from)
);
CREATE TRIGGER india_tax_ter_brackets_history BEFORE UPDATE ON india_tax_ter_brackets WHEN OLD.effective_to IS NOT NULL OR NEW.effective_to IS NULL OR NEW.rate IS NOT OLD.rate BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_tax_ter_brackets_no_delete BEFORE DELETE ON india_tax_ter_brackets BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_tax_ptkp_history BEFORE UPDATE ON india_tax_ptkp WHEN OLD.effective_to IS NOT NULL OR NEW.effective_to IS NULL OR NEW.annual_cents IS NOT OLD.annual_cents BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_tax_ptkp_no_delete BEFORE DELETE ON india_tax_ptkp BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_tax_progressive_brackets_history BEFORE UPDATE ON india_tax_progressive_brackets WHEN OLD.effective_to IS NOT NULL OR NEW.effective_to IS NULL OR NEW.rate IS NOT OLD.rate BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_tax_progressive_brackets_no_delete BEFORE DELETE ON india_tax_progressive_brackets BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_tax_rates_history BEFORE UPDATE ON india_tax_rates WHEN OLD.effective_to IS NOT NULL OR NEW.effective_to IS NULL OR NEW.rate IS NOT OLD.rate BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_tax_rates_no_delete BEFORE DELETE ON india_tax_rates BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_payroll_contribution_rates_history BEFORE UPDATE ON india_payroll_contribution_rates WHEN OLD.effective_to IS NOT NULL OR NEW.effective_to IS NULL OR NEW.rate IS NOT OLD.rate BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_payroll_contribution_rates_no_delete BEFORE DELETE ON india_payroll_contribution_rates BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_payroll_jkk_classes_history BEFORE UPDATE ON india_payroll_jkk_classes WHEN OLD.effective_to IS NOT NULL OR NEW.effective_to IS NULL OR NEW.rate IS NOT OLD.rate BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TRIGGER india_payroll_jkk_classes_no_delete BEFORE DELETE ON india_payroll_jkk_classes BEGIN SELECT RAISE(ABORT,'STATUTORY_TABLE_IMMUTABLE'); END;
CREATE TABLE india_payroll_employee_tax_profiles(
 tenant_id TEXT NOT NULL,employee_id TEXT NOT NULL,effective_from TEXT NOT NULL,
 ptkp_status TEXT NOT NULL CHECK(ptkp_status IN ('TK/0','TK/1','TK/2','TK/3','K/0','K/1','K/2','K/3')),
 has_npwp INTEGER NOT NULL CHECK(has_npwp IN (0,1)),tax_id_token TEXT,jkk_class INTEGER NOT NULL DEFAULT 1 CHECK(jkk_class BETWEEN 1 AND 5),
 employment_kind TEXT NOT NULL DEFAULT 'PERMANENT' CHECK(employment_kind IN ('PERMANENT','NON_PERMANENT_DAILY','NON_PERMANENT_MONTHLY')),
 status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')),maker TEXT NOT NULL COLLATE NOCASE,checker TEXT COLLATE NOCASE,
 PRIMARY KEY(tenant_id,employee_id,effective_from),
 FOREIGN KEY(tenant_id,employee_id) REFERENCES india_erp_hr_employee_profiles(tenant_id,id),
 CHECK(checker IS NULL OR lower(checker)!=lower(maker)),CHECK(status='pending' OR checker IS NOT NULL),
 CHECK(tax_id_token IS NULL OR tax_id_token GLOB 'vault:*')
);
CREATE TABLE india_payroll_runs(
 tenant_id TEXT NOT NULL,id TEXT NOT NULL,legal_entity_id TEXT NOT NULL,period TEXT NOT NULL CHECK(period GLOB '20[0-9][0-9]-[0-1][0-9]'),
 status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','calculated','approved','rejected','posted')),
 gross_cents INTEGER NOT NULL DEFAULT 0,pph21_cents INTEGER NOT NULL DEFAULT 0,bpjs_employer_cents INTEGER NOT NULL DEFAULT 0,
 bpjs_employee_cents INTEGER NOT NULL DEFAULT 0,net_cents INTEGER NOT NULL DEFAULT 0,
 maker TEXT NOT NULL COLLATE NOCASE,approver TEXT COLLATE NOCASE,approval_notes TEXT,version INTEGER NOT NULL DEFAULT 1,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,approved_at TEXT,
 PRIMARY KEY(tenant_id,id),UNIQUE(tenant_id,legal_entity_id,period,id),
 CHECK(approver IS NULL OR lower(approver)!=lower(maker)),
 CHECK(status NOT IN ('approved','posted') OR (approver IS NOT NULL AND length(coalesce(approval_notes,''))>=12)),
 CHECK(net_cents=gross_cents-pph21_cents-bpjs_employee_cents)
);
CREATE UNIQUE INDEX india_payroll_one_live_run ON india_payroll_runs(tenant_id,legal_entity_id,period) WHERE status IN ('draft','calculated','approved','posted');
CREATE TRIGGER india_payroll_runs_flow BEFORE UPDATE ON india_payroll_runs
WHEN NEW.version!=OLD.version+1 OR NEW.tenant_id IS NOT OLD.tenant_id OR NEW.id IS NOT OLD.id OR NEW.legal_entity_id IS NOT OLD.legal_entity_id
 OR NEW.period IS NOT OLD.period OR NEW.maker IS NOT OLD.maker
 OR NOT ((OLD.status='draft' AND NEW.status IN ('draft','calculated'))
      OR (OLD.status='calculated' AND NEW.status IN ('draft','approved','rejected'))
      OR (OLD.status='approved' AND NEW.status='posted' AND NEW.gross_cents=OLD.gross_cents AND NEW.pph21_cents=OLD.pph21_cents AND NEW.net_cents=OLD.net_cents))
 OR (OLD.status IN ('approved','posted') AND (NEW.gross_cents!=OLD.gross_cents OR NEW.pph21_cents!=OLD.pph21_cents OR NEW.bpjs_employer_cents!=OLD.bpjs_employer_cents))
BEGIN SELECT RAISE(ABORT,'PAYROLL_RUN_TRANSITION_INVALID'); END;
CREATE TRIGGER india_payroll_runs_no_delete BEFORE DELETE ON india_payroll_runs BEGIN SELECT RAISE(ABORT,'PAYROLL_RUN_IMMUTABLE'); END;
CREATE TABLE india_payroll_lines(
 tenant_id TEXT NOT NULL,run_id TEXT NOT NULL,employee_id TEXT NOT NULL,cost_center TEXT NOT NULL,
 base_salary_cents INTEGER NOT NULL CHECK(base_salary_cents>=0),allowances_cents INTEGER NOT NULL DEFAULT 0 CHECK(allowances_cents>=0),
 taxable_benefits_cents INTEGER NOT NULL DEFAULT 0,ter_category TEXT NOT NULL CHECK(ter_category IN ('A','B','C')),ter_rate TEXT NOT NULL,
 pph21_cents INTEGER NOT NULL CHECK(pph21_cents>=0),bpjs_employer_cents INTEGER NOT NULL CHECK(bpjs_employer_cents>=0),
 bpjs_employee_cents INTEGER NOT NULL CHECK(bpjs_employee_cents>=0),net_cents INTEGER NOT NULL,calc_json TEXT NOT NULL CHECK(json_valid(calc_json)),
 PRIMARY KEY(tenant_id,run_id,employee_id),FOREIGN KEY(tenant_id,run_id) REFERENCES india_payroll_runs(tenant_id,id),
 FOREIGN KEY(tenant_id,employee_id) REFERENCES india_erp_hr_employee_profiles(tenant_id,id),
 CHECK(net_cents=base_salary_cents+allowances_cents-pph21_cents-bpjs_employee_cents)
);
CREATE TRIGGER india_payroll_lines_lock BEFORE INSERT ON india_payroll_lines
WHEN NOT EXISTS(SELECT 1 FROM india_payroll_runs r WHERE r.tenant_id=NEW.tenant_id AND r.id=NEW.run_id AND r.status='draft')
BEGIN SELECT RAISE(ABORT,'PAYROLL_RUN_LOCKED'); END;
CREATE TRIGGER india_payroll_lines_immutable BEFORE UPDATE ON india_payroll_lines BEGIN SELECT RAISE(ABORT,'PAYROLL_LINE_IMMUTABLE'); END;
CREATE TRIGGER india_payroll_lines_no_delete BEFORE DELETE ON india_payroll_lines
WHEN NOT EXISTS(SELECT 1 FROM india_payroll_runs r WHERE r.tenant_id=OLD.tenant_id AND r.id=OLD.run_id AND r.status='draft')
BEGIN SELECT RAISE(ABORT,'PAYROLL_RUN_LOCKED'); END;
